import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    FaCalendarAlt, FaCheck, FaPlus, FaSync, 
    FaSave, FaBullseye, FaTasks, FaSpinner, FaRocket
} from 'react-icons/fa';
import { motion } from 'framer-motion';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedTask, setSelectedTask] = useState(null);
    const [taskNote, setTaskNote] = useState('');
    
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();
    const currentDay = today.getDate();
    const currentWeekDay = today.toLocaleDateString('en-US', { weekday: 'long' });
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 
                        'July', 'August', 'September', 'October', 'November', 'December'];

    const targetDate = new Date(2026, 10, 30);
    const daysRemaining = Math.max(0, Math.ceil((targetDate - today) / (1000 * 60 * 60 * 24)));

    useEffect(() => {
        if (user && token) fetchTasks();
    }, [user, token]);

    const fetchTasks = async () => {
        try {
            const res = await axios.get(`http://localhost:8081/api/tasks/user/${user.id}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setTasks(res.data);
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        setCreating(true);
        try {
            const date = new Date(currentYear, currentMonth, day);
            const res = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${date.toISOString().split('T')[0]}`,
                {}, { headers: { 'Authorization': `Bearer ${token}` } }
            );
            setTasks([...tasks, res.data]);
            toast.success(`✅ Tasks created for ${monthNames[currentMonth]} ${day}`);
        } catch (error) {
            toast.error('Failed to create tasks');
        } finally {
            setCreating(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, [field]: !task[field] };
        
        try {
            const res = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            
            setTasks(tasks.map(t => t.id === taskId ? res.data : t));
            
            if (updatedTask[field]) {
                toast.success('🤲 Alhamdulillah! Task done!');
            } else {
                toast.info('Re-opened task');
            }
        } catch (error) {
            toast.error(`❌ ${error.response?.data?.message || 'Update failed'}`);
        }
    };

    const handleDayClick = async (day) => {
        setSelectedDay(day);
        const dayTasks = tasks.filter(task => task.day === day);
        if (dayTasks.length === 0 && !creating) {
            await createTaskForDay(day);
        }
    };

    const getDayTasks = (day) => tasks.filter(task => task.day === day);
    const getDayStatus = (day) => {
        const dayTasks = getDayTasks(day);
        if (dayTasks.length === 0) return 'empty';
        const completed = dayTasks.filter(t => t.overallCompleted).length;
        return completed === dayTasks.length ? 'done' : (completed > 0 ? 'partial' : 'started');
    };

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted).length;
    const progressPercent = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    const calculateStreak = () => {
        let streak = 0;
        const sorted = [...tasks].sort((a, b) => a.day - b.day);
        for (const task of sorted) {
            if (task.overallCompleted === true) streak++;
            else break;
        }
        return streak;
    };
    const streak = calculateStreak();

    if (loading) return (
        <div className="flex justify-center items-center h-[60vh]">
            <FaSpinner className="animate-spin text-purple-600 text-4xl" />
        </div>
    );

    const taskLabels = [
        { key: 'javaCompleted', label: 'Java (1.5h)', icon: '☕' },
        { key: 'leetcodeCompleted', label: 'LeetCode (1+)', icon: '💻' },
        { key: 'dsaCompleted', label: 'DSA/OOP (1h)', icon: '📊' },
        { key: 'sqlCompleted', label: 'SQL/APIs (1h)', icon: '🗄️' },
        { key: 'projectCompleted', label: 'Project (2-3h)', icon: '🚀' },
        { key: 'githubCompleted', label: 'GitHub/Portfolio', icon: '📁' }
    ];

    const getFirstDayOfMonth = (year, month) => new Date(year, month, 1).getDay(); // 0 = Sun, 6 = Sat
    const firstDay = getFirstDayOfMonth(currentYear, currentMonth);
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

    return (
        <div className="min-h-screen bg-gray-50 p-6 font-sans">
            {/* --- MODAL --- */}
            {isModalOpen && selectedTask && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm">
                    <div className="bg-white rounded-2xl shadow-2xl p-6 max-w-md w-full mx-4">
                        <h5 className="font-bold text-lg text-gray-800 mb-4">{selectedTask.label} Note</h5>
                        <textarea 
                            value={taskNote} 
                            onChange={(e) => setTaskNote(e.target.value)} 
                            className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 outline-none resize-none" 
                            rows="4" 
                            placeholder="What did you learn today?" 
                        />
                        <div className="flex justify-end gap-3 mt-4">
                            <button onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-gray-600 font-medium hover:bg-gray-100 rounded-xl">Cancel</button>
                            <button onClick={async () => {
                                if (!selectedTask) return;
                                try {
                                    const updatedTask = { ...selectedTask.task, notes: taskNote };
                                    const res = await axios.put(`http://localhost:8081/api/tasks/${selectedTask.task.id}`, updatedTask, { headers: { Authorization: `Bearer ${token}` } });
                                    setTasks(tasks.map(t => t.id === selectedTask.task.id ? res.data : t));
                                    toast.success('💾 Note saved!');
                                    setIsModalOpen(false);
                                } catch (error) {
                                    toast.error('Failed to save note');
                                }
                            }} className="px-4 py-2 bg-purple-600 text-white font-medium rounded-xl hover:bg-purple-700">Save Note</button>
                        </div>
                    </div>
                </div>
            )}

            {/* --- HEADER --- */}
            <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} className="relative rounded-2xl p-8 mb-8 text-white shadow-lg overflow-hidden bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-500">
                <div className="relative z-10 flex justify-between items-center">
                    <div>
                        <h1 className="text-3xl font-bold tracking-tight mb-1">Today is {currentDay} {monthNames[currentMonth]} {currentYear}</h1>
                        <p className="text-indigo-200">{currentWeekDay}</p>
                    </div>
                    <div className="text-right bg-white/10 p-4 rounded-xl backdrop-blur-sm">
                        <p className="text-indigo-200 text-sm">Days Left to Goal</p>
                        <p className="text-4xl font-extrabold">{daysRemaining}</p>
                        <p className="text-indigo-200 text-xs mt-1">Target: 30 Nov 2026</p>
                    </div>
                </div>
                <div className="absolute -top-20 -right-20 w-96 h-96 bg-purple-500 rounded-full blur-[100px] opacity-30" />
            </motion.div>

            {/* --- STATS CARDS --- */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                <div className="bg-white rounded-xl p-5 shadow-sm border border-gray-100">
                    <div className="flex items-center gap-2 mb-2"><div className="bg-purple-100 p-2 rounded-lg text-purple-600"><FaRocket /></div><span className="text-sm font-semibold text-gray-700">Progress</span></div>
                    <h3 className="text-2xl font-bold text-gray-800">{progressPercent}%</h3>
                    <div className="w-full h-1.5 bg-gray-200 rounded-full mt-2"><div className="h-1.5 bg-purple-600 rounded-full" style={{ width: `${progressPercent}%` }} /></div>
                </div>
                <div className="bg-white rounded-xl p-5 shadow-sm border border-gray-100">
                    <div className="flex items-center gap-2 mb-2"><div className="bg-green-100 p-2 rounded-lg text-green-600"><FaTasks /></div><span className="text-sm font-semibold text-gray-700">Tasks Done</span></div>
                    <h3 className="text-2xl font-bold text-gray-800">{completedTasks} <span className="text-gray-400 text-lg font-normal">/ {totalTasks}</span></h3>
                </div>
                <div className="bg-white rounded-xl p-5 shadow-sm border border-gray-100">
                    <div className="flex items-center gap-2 mb-2"><div className="bg-orange-100 p-2 rounded-lg text-orange-600"><FaCheck /></div><span className="text-sm font-semibold text-gray-700">Streak</span></div>
                    <h3 className="text-2xl font-bold text-gray-800">{streak} <span className="text-gray-400 text-lg font-normal">Days</span></h3>
                    <p className="text-xs text-green-500 font-medium mt-1">Keep it up! 🔥</p>
                </div>
                <div className="bg-white rounded-xl p-5 shadow-sm border border-gray-100">
                    <div className="flex items-center gap-2 mb-2"><div className="bg-blue-100 p-2 rounded-lg text-blue-600"><FaCalendarAlt /></div><span className="text-sm font-semibold text-gray-700">Days Left</span></div>
                    <h3 className="text-2xl font-bold text-gray-800">{daysRemaining}</h3>
                </div>
            </div>

            {/* --- CALENDAR & TASKS --- */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                
                {/* CALENDAR */}
                <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="font-bold text-lg text-gray-800 flex items-center gap-2"><FaCalendarAlt className="text-purple-600" /> Monthly Calendar</h3>
                        <div className="flex gap-3 text-xs font-medium">
                            <span className="flex items-center gap-1 text-green-600"><span className="w-2 h-2 rounded-full bg-green-500"></span> Completed</span>
                            <span className="flex items-center gap-1 text-orange-500"><span className="w-2 h-2 rounded-full bg-orange-400"></span> Partial</span>
                            <span className="flex items-center gap-1 text-purple-600"><span className="w-2 h-2 rounded-full bg-purple-500"></span> Started</span>
                        </div>
                    </div>

                    <div className="grid grid-cols-7 gap-2 text-center mb-4">
                        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => (
                            <div key={d} className="text-gray-400 text-xs font-semibold py-2">{d}</div>
                        ))}
                    </div>

                    <div className="grid grid-cols-7 gap-2 text-center">
                        {/* Empty slots for days before month starts */}
                        {Array.from({ length: firstDay }).map((_, i) => (
                            <div key={`empty-${i}`} className="aspect-square bg-transparent"></div>
                        ))}
                        
                        {/* Actual Days */}
                        {Array.from({ length: daysInMonth }).map((_, i) => {
                            const day = i + 1;
                            const status = getDayStatus(day);
                            const isToday = day === currentDay;
                            
                            // Determines dot color in the center
                            let dotColor = 'bg-gray-200';
                            if (isToday) dotColor = 'bg-purple-600';
                            else if (status === 'done') dotColor = 'bg-green-500';
                            else if (status === 'partial') dotColor = 'bg-orange-400';
                            else if (status === 'started') dotColor = 'bg-purple-500';
                            
                            return (
                                <button 
                                    key={day}
                                    onClick={() => handleDayClick(day)}
                                    className={`aspect-square rounded-xl border font-medium text-sm transition-all flex flex-col items-center justify-center gap-1 
                                        ${isToday 
                                            ? 'border-2 border-purple-600 bg-purple-50 text-purple-700' // Today's box
                                            : 'border-gray-200 text-gray-700 hover:bg-gray-50'
                                        }`}
                                >
                                    <span>{day}</span>
                                    {/* The Status Dot */}
                                    <div className={`w-1.5 h-1.5 rounded-full ${dotColor}`}></div>
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* TODAY'S TASKS */}
                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="font-bold text-lg text-gray-800">
                            {selectedDay ? `📋 Day ${selectedDay}` : 'Select a Day'}
                        </h3>
                        {selectedDay && <span className="text-xs bg-purple-100 text-purple-600 px-3 py-1 rounded-full font-semibold">{getDayTasks(selectedDay).length}</span>}
                    </div>

                    {selectedDay ? (
                        <div className="space-y-3">
                            {taskLabels.map(({ key, label, icon }) => {
                                const task = getDayTasks(selectedDay)[0];
                                const isCompleted = task ? task[key] : false;
                                return (
                                    <div key={key} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${isCompleted ? 'border-green-200 bg-green-50' : 'border-gray-200 bg-white'}`}>
                                        <div className="flex items-center gap-3">
                                            <span className="text-lg">{icon}</span>
                                            <span className={`text-sm font-medium ${isCompleted ? 'line-through text-green-600' : 'text-gray-700'}`}>{label}</span>
                                        </div>
                                        <button 
                                            onClick={() => task && toggleTask(task.id, key)}
                                            className={`text-xs font-bold px-4 py-1.5 rounded-full transition-all shadow-sm ${isCompleted ? 'bg-green-500 text-white hover:bg-green-600' : 'bg-purple-500 text-white hover:bg-purple-600'}`}
                                        >
                                            {isCompleted ? '🤲 Done' : 'Mark Done'}
                                        </button>
                                    </div>
                                );
                            })}
                            {getDayTasks(selectedDay).length === 0 && !creating && (
                                <div className="text-center py-12 border-2 border-dashed border-gray-200 rounded-xl bg-gray-50">
                                    <FaPlus className="mx-auto text-gray-400 text-3xl mb-3" />
                                    <p className="text-gray-500 text-sm font-medium mb-3">No tasks for this day</p>
                                    <button onClick={() => handleDayClick(selectedDay)} className="bg-purple-600 text-white text-sm font-semibold px-6 py-2 rounded-full hover:bg-purple-700 shadow-sm">
                                        Generate Tasks
                                    </button>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="h-[300px] flex flex-col items-center justify-center text-gray-400">
                            <FaCalendarAlt size={48} className="text-gray-200 mb-3" />
                            <p className="font-medium text-gray-500">👆 Pick a date on the calendar</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default DailyTracker;
